import {orient, goTo, hunt, disengage, outcome, note, account, stopped, type Outcome, type Present} from 'play';

/**
 * Fly to sol_nebula and hunt for 2 fights. No matter how the hunt ends — done, refused,
 * failed, or a thrown error — disengage() must run at the end of the program, and the
 * hunt Outcome is returned.
 */
export default async function main() {
  // 1. See where we stand.
  const start = await orient();
  const here = start.detail?.present?.location ?? null;
  const atNebula = here?.poi_id === 'sol_nebula';

  // 2. Get to sol_nebula if we are not already there.
  if (!atNebula) {
    const trip = await goTo('sol_nebula');
    if (trip.status !== 'done') {
      // Cannot reach the nebula — clean up and hand back the reason, with the disengage.
      const cleanup = await disengage();
      return outcome(
        `could not reach sol_nebula (${trip.why ?? trip.did}); disengaged at end`,
        trip.status,
        {reason: trip.why, trip_detail: trip.detail, disengaged: cleanup.status === 'done'},
      );
    }
  }

  // 3. The hunt itself — two fights. Whatever comes back, we must disengage afterwards.
  let huntOutcome: Outcome<unknown>;
  try {
    huntOutcome = await hunt({poi: 'sol_nebula', fights: 2});
  } catch (err) {
    // A thrown error (a refused raw command surfaces this way, a loadout/precondition break, etc.)
    huntOutcome = outcome(
      `hunt threw: ${err instanceof Error ? err.message : String(err)}`,
      'failed',
      {threw: true},
    );
  }

  // 4. The guaranteed disengage — the hunt is finished by every path above, so a battle, if
  //    one is holding us, is here to break. Runs whether the hunt was done, partial, refused,
  //    failed, or threw.
  const cleanup = await disengage();
  note(
    `hunt (${huntOutcome.status}) ended; disengaged — battle cleared: ${cleanup.status === 'done'}`
  );

  // 5. Return the hunt Outcome as the program's result.
  return huntOutcome;
}
