import {orient, prices, missions, note, Outcome} from 'play';

function creditsFromNow(now: unknown): number {
  if (!now || typeof now !== 'object') return 0;
  const credits = (now as {credits?: unknown}).credits;
  if (typeof credits === 'number' && Number.isFinite(credits)) return credits;
  const parsed = Number(credits);
  return Number.isFinite(parsed) ? parsed : 0;
}

function topBuyQuote(detail: unknown): {item_id: string; best_buy: number} | null {
  if (!detail || typeof detail !== 'object') return null;
  const quotes = (detail as {quotes?: unknown}).quotes;
  if (!Array.isArray(quotes)) return null;

  let best: {item_id: string; best_buy: number} | null = null;
  for (const quote of quotes) {
    if (!quote || typeof quote !== 'object') continue;
    const q = quote as {item_id?: unknown; best_buy?: unknown};
    const parsedBuy = Number(q.best_buy);
    if (!Number.isFinite(parsedBuy)) continue;
    const itemId = typeof q.item_id === 'string' ? q.item_id : String(q.item_id ?? '');
    if (!best || parsedBuy > best.best_buy) {
      best = {item_id: itemId, best_buy: parsedBuy};
    }
  }
  return best;
}

function missionCountFromDetail(detail: unknown): number {
  if (Array.isArray(detail)) return detail.length;
  if (!detail || typeof detail !== 'object') return 0;

  const obj = detail as Record<string, unknown>;
  for (const key of ['missions', 'board', 'available', 'active', 'list', 'rows', 'items']) {
    const value = obj[key];
    if (Array.isArray(value)) return value.length;
  }

  for (const key of ['count', 'length', 'total']) {
    const value = obj[key];
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return Math.max(0, Math.floor(parsed));
  }

  return 0;
}

export default async function main() {
  const [orientO, priceO, missionO] = (await Promise.all([
    orient(),
    prices(),
    missions(),
  ])) as unknown as [Outcome<unknown>, Outcome<unknown>, Outcome<unknown>];

  const credits = creditsFromNow(orientO.now ?? priceO.now ?? null);
  const top = topBuyQuote(priceO.detail ?? null);
  const missionCount = missionCountFromDetail(missionO.detail ?? null);

  await note(
    `credits: ${credits}; highest_best_buy: ${top ? top.item_id : 'none'}; missions: ${missionCount}`,
  );

  return priceO;
}

