/** Pause the program for ms milliseconds (wall clock). */
function wait(ms: number) {
  return new Promise<void>(resolve => setTimeout(resolve, ms));
}

export default async function main() {
  const MAX_ATTEMPTS = 6;   // 5 retries + the first try
  const BASE_DELAY_MS = 1000; // 1s, then 2, 4, 8, 16 ...

  let last: Outcome<unknown> = await goTo('sol_belt');

  // Retry only a *transient* failure. refused means the rules said no (no counter /
  // no route / no fuel) — do not retry. done (or any non-failed status) is terminal.
  for (let attempt = 1; attempt < MAX_ATTEMPTS; attempt++) {
    if (stopped()) return last;                 // the run was asked to stop; end early
    if (last.status !== 'failed') return last;  // done / partial / refused: stop here

    await wait(BASE_DELAY_MS * 2 ** (attempt - 1)); // 1s, 2s, 4s, 8s, 16s before the next try
    if (stopped()) return last;
    last = await goTo('sol_belt');
