  // All 6 attempts were `failed`; the task says to return the last trip Outcome.
  if (last.status === 'failed') {
    return outcome(
      'goTo sol_belt failed 6 times (transient failure persisted through 5 retries)',
      {status: 'failed'},
      last.detail
    );
  }
  return last;
}
