import {
  orient,
  missions,
  acceptMission,
  completeMissions,
  note,
  outcome,
  type Outcome,
} from 'play';
import type { MissionInfo } from '@spacemolt/lib';

// A loose number extractor: mission rewards differ in shape across the game, so read the
// first field that looks like a reward credit value rather than assuming one name.
function rewardOf(m: MissionInfo): number {
  const raw = (m ?? {}) as unknown as Record<string, unknown>;
  const keys = ['reward_credits', 'credits_reward', 'reward', 'bounty', 'credits', 'payout'];
  for (const k of keys) {
    const v = raw[k];
    if (typeof v === 'number' && Number.isFinite(v)) return v;
  }
  for (const k of keys) {
    const v = raw[k];
    if (v && typeof v === 'object') {
      const o = v as Record<string, unknown>;
      for (const kk of ['credits', 'amount', 'value', 'total']) {
        if (typeof o[kk] === 'number' && Number.isFinite(o[kk])) return o[kk] as number;
      }
    }
  }
  return 0;
}

function missionId(m: MissionInfo): string | undefined {
  const r = (m ?? {}) as unknown as Record<string, unknown>;
  const v = r.id ?? r.mission_id ?? r.contract_id;
  return typeof v === 'string' && v ? v : undefined;
}

// Free slots on the mission board: 0 when at the limit.
function freeSlots(look: Outcome): number {
  const m = (look as unknown as Record<string, unknown>).missions as
    | { free?: number; available?: number; capacity?: number; taken?: number }
    | undefined;
  if (!m) return 0;
  if (typeof m.free === 'number') return Math.max(0, Math.floor(m.free));
  if (typeof m.available === 'number') return Math.max(0, Math.floor(m.available));
  if (typeof m.capacity === 'number' && typeof m.taken === 'number')
    return Math.max(0, Math.floor(m.capacity) - Math.floor(m.taken));
  return 0;
}

export default async function main(): Promise<Outcome<unknown>> {
  await orient();

  let accepted = 0;
  const board = await missions();

  // The board rows — accept those worth ≥ 100, cheapest/roundest first within that band,
  // bounded by the free slots on the board.
  let list: MissionInfo[] = [];
  const rawDetail = (board.detail ?? {}) as unknown as Record<string, unknown>;
  for (const key of ['listings', 'missions', 'available', 'open']) {
    const v = rawDetail[key];
    if (Array.isArray(v)) {
      list = v as MissionInfo[];
      break;
    }
  }

  let free = freeSlots(board);
  const eligible = list
    .filter(m => {
      const r = rewardOf(m);
      const id = missionId(m);
      return id !== undefined && r >= 100;
    })
    .sort((a, b) => rewardOf(a) - rewardOf(b));

  for (const m of eligible) {
    const id = missionId(m);
    if (!id) continue;
    if (free <= 0) break; // no more free slots; the board has a hard limit
    const a = await acceptMission(id);
    if (a.status !== 'done') {
      note(`stop accepting: acceptMission(${id}) ${a.status} — ${a.why ?? ''}`);
      break; // first non-done accept ends the accepting loop
    }
    accepted += 1;
    free -= 1;
  }

  const done = await completeMissions();
  if (done.status !== 'done') {
    note(`completeMissions not done (${done.status}) — ${done.why ?? 'no reason given'}`);
  }

  return outcome(
    `accepted ${accepted} mission(s) and settled the board`,
    'done',
    { accepted },
  );
}
```

A couple of notes on the decisions in there:

- **Reward threshold**: the lib doesn't fix one reward field name across board shapes, so `rewardOf()` scans the plausible credit fields (`reward_credits`, `reward`, `bounty`, `payout`, plus nested `credits`/`amount`) and treats the first number it finds as the reward. Missions with no readable reward score 0 and are skipped, which keeps "at least 100" safe rather than accepting unknowns.
- **Free slots**: `freeSlots()` reads the board's capacity from `free`/`available` or `capacity - taken` in the `missions()` detail. If the detail doesn't expose one, it falls back to 0 and accepts nothing — the safest read of "no more than the free slots allow."
- **Stopping rule**: the loop breaks on the first `acceptMission` that isn't `done`, exactly as specified, and notes the reason into the stream.
- **`completeMissions()`** runs unconditionally after; a non-done result is noted (carrying on, no return) and the final `outcome()` reports the accepted count with `detail: {accepted}`.

