import { goTo, Outcome } from 'play';

// Helper to sleep
function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export default async function main() {
  let outcome: Outcome<any>;

  for (let i = 0; i < 6; i++) {
    outcome = await goTo('sol_belt');

    // If successful or refused, return immediately
    if (outcome.status === 'done' || outcome.status === 'refused') {
      return outcome;
    }

    // If failed, retry with backoff if we have attempts left
    if (outcome.status === 'failed') {
      // i is 0 to 5.
      // If i < 5, we have more attempts left.
      if (i < 5) {
        const delayMs = Math.pow(2, i) * 1000; // 1s, 2s, 4s, 8s, 16s
        await sleep(delayMs);
      } else {
        // This was the 6th attempt (i=5), no retries left
        return outcome;
      }
    }
  }

  // Fallback, though the loop should always return
  return outcome;
}
