```ts
import {orient, missions, acceptMission, completeMissions, note, outcome, Outcome} from 'play';

export default async function main() {
  await orient();
  const board = await missions();

  // Free slots: how many missions I may have active at once.
  const free =
    board.detail?.profile?.free_slots ??
    board.detail?.profile?.freeSlots ??
    (typeof board.detail?.profile?.active === 'number'
      ? Math.max(0, (board.detail?.profile?.capacity ?? 0) - (board.detail?.profile?.active ?? 0))
      : undefined);

  const maxBySlots = typeof free === 'number' ? free : 1_000_000;

  // Candidate board rows, reward >= 100.
  const cands: any[] = ((board.detail?.listings ?? []) as any[]).filter(
    m =>
      (m.reward ?? m.base_reward ?? m.reward_credits ?? m.credits ?? 0) >= 100 &&
      (m.id ?? m.mission_id ?? m.contract_id ?? m.contract?.id)
  );

  let accepted = 0;
  for (const c of cands) {
    if (accepted >= maxBySlots) break;
    const id: string = c.id ?? c.mission_id ?? c.contract_id ?? c.contract?.id;
    const acc = await acceptMission(id);
    if (acc.status !== 'done') {
      note(`stopped accepting at ${id}: ${acc.why ?? acc.status}`);
      break;
    }
    accepted++;
  }

  const done = await completeMissions();
  if (done.status !== 'done') {
    note(`completeMissions not done: ${done.why ?? done.status}`);
  }

  return outcome(`accepted ${accepted} mission(s)`, 'done', {accepted});
}
```

What it does, in order:
1. `orient()` to set the present (docked at sol_station).
2. `missions()` to read the local board.
3. Filters listings to reward ≥ 100 and caps how many to accept at the profile's free slots (falls back to an effectively-unlimited cap if the profile doesn't expose a number, and to the ≥100 count otherwise).
4. Loops `acceptMission(id)` in order, stops at the first one whose status is not `done`.
5. `completeMissions()`; if not `done`, `note` its `why` and carry on (no early return).
6. Returns an `outcome(...)` whose `did` states how many were accepted and whose `detail` is `{accepted}`.

