import {
  orient,
  gatherUntil,
  sell,
  service,
  completeMissions,
  note,
} from 'play';
import type { Outcome } from 'play';

export default async function main() {
  // Gather one trip to kepler_belt, returning to kepler_station.
  const trip = await gatherUntil({ poi: 'kepler_belt', base: 'kepler_station' });
  if (trip.status !== 'done') return trip;

  // Sell the copper_ore this trip settled, from the store.
  const copperSettled = (trip.detail.settled ?? []).filter(r => r.item_id === 'copper_ore');
  let svc: Outcome<unknown> | null = null;

  if (copperSettled.length > 0) {
    await sell(copperSettled, { from: 'store' });
  }

  // Service the ship, and complete missions (a not-done there is fine).
  svc = await service();
  await completeMissions();

  // Whatever happened, the last thing the program does is note current credits.
  try {
    const look = await orient();
    note(`current credits: ${look.now?.credits ?? 0}`);
  } catch {
    note('could not read credits (orient threw)');
  }

  return svc;
}
